	private static void awaitCloseLease(Thread closer) {
		long deadline = System.nanoTime() + Duration.ofSeconds(10).toNanos();
		while (closer.isAlive() && System.nanoTime() < deadline) {
			for (var frame : closer.getStackTrace()) {
				if (frame.getMethodName().equals("closeNativeDataset")) {
					return;
				}
			}
			Thread.yield();
		}
		fail("Dataset close did not reach its lease");
	}

	private static long[] unwrittenBuffer(int demand) {
		long[] buffer = new long[demand * 4];
		Arrays.fill(buffer, UNWRITTEN);
		return buffer;
	}

	private static int writtenRows(long[] buffer) {
		int row = 0;
		while (row * 4 < buffer.length && buffer[row * 4] != UNWRITTEN) {
			row++;
		}
		return row;
	}

	private final class ExternalCursor implements RecordIterator {
		private final RecordIterator delegate;

		private ExternalCursor(RecordIterator delegate) {
			this.delegate = delegate;
		}

		@Override
		public long[] next() {
			throw new AssertionError("Keep virtual bulk dispatch for external cursors");
		}

		@Override
		public int fill(long[] buffer, int maxRows) {
			delegateFills++;
			largestDelegateFill = Math.max(largestDelegateFill, maxRows);
			return delegate.fill(buffer, maxRows);
		}

		@Override
		public void close() {
			delegate.close();
		}
	}
